#!/bin/sh
# Generated by `cargo xtask paper fetch-script` from xtask/bench/datasets.toml.
# Do not edit: change datasets.toml and regenerate.
#
# Fetches the paper datasets (D95) and builds the derived inputs. CI never
# runs this. Usage: sh paper/fetch-datasets.sh [NAME]
# NAME is one dataset or derived input; what it needs is fetched or built
# too, and an unknown NAME is an error.
# GLOCI_BENCH_CACHE sets the cache (default target/bench-data/cache).
# Derived inputs without a recorded sha256 are UNVERIFIED: the script then
# exits 1 unless GLOCI_ALLOW_UNPINNED=1.
# Needs bash (derived commands run under `bash -o pipefail`) and curl.
#
# Tools the derived inputs need, as pinned in xtask/docker/Dockerfile.bench
# (run this in that image, or install the same versions):
#   rust=1.99.1
#   bedtools=2.31.1
#   bedops=2.4.41
#   vcftools=0.1.16
#   htslib=1.21
#   bcftools=1.21
#   samtools=1.21
#   mosdepth=0.3.10
#   hyperfine=2.0.0
#   bedtk=1.1
#   coreutils=9.12
#   gawk=5.3.1
#   time=1.9-0.2
set -eu
command -v bash >/dev/null 2>&1 || { echo "fetch-datasets.sh needs bash (for pipefail)" >&2; exit 1; }
ROOT=$(cd "$(dirname "$0")/.." && pwd)
CACHE=${GLOCI_BENCH_CACHE:-$ROOT/target/bench-data/cache}
ONLY=${1:-}
KNOWN=' 1kg-30x-chr20 gencode-v46-gtf encode-ccre-v4 encode-ctcf-k562-peaks encode-ctcf-k562-fc gnomad-v4.1-exomes-chr22 encode-ctcf-k562-bam exons-unsorted.bed exons.bed ccre.bed ccre.bed.gz exons.bed.gz ctcf-fc.bedgraph ctcf-fc.bed5 1kg-chr20.bcf 1kg-chr20.p1.vcf.gz 1kg-chr20.p2.vcf.gz ctcf-k562.bam ctcf-k562.cram ctcf-peaks.bed hg38.lex.genome '
if [ -n "$ONLY" ]; then
  case "$KNOWN" in *" $ONLY "*) ;; *) echo "unknown dataset or derived input: $ONLY" >&2; exit 2 ;; esac
fi
UNPINNED=
NUNPINNED=0
mkdir -p "$CACHE"

# want NAME DEPENDENTS: NAME itself, or an item that needs it.
want() { [ -z "$ONLY" ] || [ "$ONLY" = "$1" ] || case " $2 " in *" $ONLY "*) true ;; *) false ;; esac; }
md5_of() { if command -v md5sum >/dev/null 2>&1; then md5sum "$1" | cut -d' ' -f1; else md5 -q "$1"; fi; }
sha256_of() { if command -v sha256sum >/dev/null 2>&1; then sha256sum "$1" | cut -d' ' -f1; else shasum -a 256 "$1" | cut -d' ' -f1; fi; }
# sidecars NAME: the index extensions a derived input must have.
sidecars() {
  case "$1" in
    *.bam) echo bai ;; *.cram) echo crai ;; *.bcf) echo csi ;;
    *.vcf.gz|*.bed.gz) echo tbi ;; *) echo ;;
  esac
}

# fetch NAME URL FILE MD5 DEPENDENTS: the provider's md5 is the check.
fetch() {
  want "$1" "$5" || return 0
  if [ ! -e "$CACHE/$3" ]; then
    echo "fetching $1" >&2
    curl -fsSL --retry 3 --proto '=https' -o "$CACHE/$3.tmp" "$2"
    mv "$CACHE/$3.tmp" "$CACHE/$3"
  fi
  got=$(md5_of "$CACHE/$3")
  if [ "$got" != "$4" ]; then
    mv "$CACHE/$3" "$CACHE/$3.bad"
    echo "md5 mismatch for $1: expected $4, got $got; moved the file to $CACHE/$3.bad (delete it and run again)" >&2
    exit 1
  fi
}

# derive NAME SHA256 COMMAND DEPENDENTS: COMMAND sees IN, IN2... and OUT.
# Index files go first and the result last, so an interrupted run leaves
# no main file and the next run derives again.
derive() {
  want "$1" "$4" || return 0
  complete=1
  [ -e "$CACHE/$1" ] || complete=0
  for e in $(sidecars "$1"); do [ -e "$CACHE/$1.$e" ] || complete=0; done
  if [ "$complete" = 0 ]; then
    echo "deriving $1" >&2
    rm -f "$CACHE/$1" "$CACHE/$1.partial" "$CACHE/$1.partial".*
    OUT="$CACHE/$1.partial" LC_ALL=C bash -o pipefail -c "$3"
    for f in "$CACHE/$1.partial".*; do
      if [ -e "$f" ]; then mv "$f" "$CACHE/$1.${f##*.partial.}"; fi
    done
    for e in $(sidecars "$1"); do
      [ -e "$CACHE/$1.$e" ] || { echo "$1: the command did not write its .$e index" >&2; exit 1; }
    done
    mv "$CACHE/$1.partial" "$CACHE/$1"
  fi
  if [ -z "$2" ]; then
    echo "UNVERIFIED: $1 has no sha256 in datasets.toml (got $(sha256_of "$CACHE/$1"))" >&2
    UNPINNED="$UNPINNED $1"
    NUNPINNED=$((NUNPINNED + 1))
  elif [ "$(sha256_of "$CACHE/$1")" != "$2" ]; then
    echo "sha256 mismatch for $1: expected $2; delete $CACHE/$1 and run again" >&2
    exit 1
  fi
}

fetch '1kg-30x-chr20' 'https://ftp.1000genomes.ebi.ac.uk/vol1/ftp/data_collections/1000G_2504_high_coverage/working/20220422_3202_phased_SNV_INDEL_SV/1kGP_high_coverage_Illumina.chr20.filtered.SNV_INDEL_SV_phased_panel.vcf.gz' '1kGP_high_coverage_Illumina.chr20.filtered.SNV_INDEL_SV_phased_panel.vcf.gz' '34a9a5dbfb285e7eb9d1f2881953014b' '1kg-chr20.bcf 1kg-chr20.p1.vcf.gz 1kg-chr20.p2.vcf.gz'
fetch 'gencode-v46-gtf' 'https://ftp.ebi.ac.uk/pub/databases/gencode/Gencode_human/release_46/gencode.v46.annotation.gtf.gz' 'gencode.v46.annotation.gtf.gz' '68070e3c87f6a0e70af6e4ff4d55f61c' 'exons-unsorted.bed exons.bed exons.bed.gz'
fetch 'encode-ccre-v4' 'https://www.encodeproject.org/files/ENCFF420VPZ/@@download/ENCFF420VPZ.bed.gz' 'ENCFF420VPZ.bed.gz' 'ea1820bd71581ba01c94fc600fbf794d' 'ccre.bed ccre.bed.gz'
fetch 'encode-ctcf-k562-peaks' 'https://www.encodeproject.org/files/ENCFF769AUF/@@download/ENCFF769AUF.bed.gz' 'ENCFF769AUF.bed.gz' '7d086cac19c5311a77b7e21e3d931435' 'ctcf-peaks.bed'
fetch 'encode-ctcf-k562-fc' 'https://www.encodeproject.org/files/ENCFF979PWH/@@download/ENCFF979PWH.bigWig' 'ENCFF979PWH.bigWig' '4a1da9d7819bc622c27cd60950d28abb' 'ctcf-fc.bedgraph ctcf-fc.bed5'
fetch 'gnomad-v4.1-exomes-chr22' 'https://storage.googleapis.com/gcp-public-data--gnomad/release/4.1/vcf/exomes/gnomad.exomes.v4.1.sites.chr22.vcf.bgz' 'gnomad.exomes.v4.1.sites.chr22.vcf.bgz' 'dcf191563e69054a71bd4dc77862799a' ''
fetch 'encode-ctcf-k562-bam' 'https://www.encodeproject.org/files/ENCFF834MPG/@@download/ENCFF834MPG.bam' 'ENCFF834MPG.bam' '22477d07776b89e20b0458ed873306d4' 'ctcf-k562.bam ctcf-k562.cram ctcf-peaks.bed'

export IN="$CACHE/gencode.v46.annotation.gtf.gz"
derive 'exons-unsorted.bed' '915ed366960cbd4ec72a1f3ee54d48c9b3e29c72b924bf12eba148ec87c1dd69' 'zcat "$IN" | gawk -F'\''\t'\'' -v OFS='\''\t'\'' '\''$3=="exon"{match($9,/gene_name "[^"]+"/);print $1,$4-1,$5,substr($9,RSTART+11,RLENGTH-12),0,$7}'\'' > "$OUT"' 'exons.bed exons.bed.gz'
export IN="$CACHE/exons-unsorted.bed"
derive 'exons.bed' 'ebd86df27ee539d7422d667cbe30fa4fca3a08f5dd096dca92a7dcf5123632e3' 'sort -k1,1 -k2,2n -k3,3n -s "$IN" > "$OUT"' 'exons.bed.gz'
export IN="$CACHE/ENCFF420VPZ.bed.gz"
derive 'ccre.bed' '5b2c8d03c699baf152c982bba95fd168beae2b0416f2181d643f9c2bb9ead5f3' 'zcat "$IN" | cut -f1-6 | sort -k1,1 -k2,2n -s > "$OUT"' 'ccre.bed.gz'
export IN="$CACHE/ccre.bed"
derive 'ccre.bed.gz' '558e3ef6f06253d939c699f973989a6a6d9498cc8d83166ccfc6273a00dd744c' 'bgzip -c "$IN" > "$OUT" && tabix -p bed "$OUT"' ''
export IN="$CACHE/exons.bed"
derive 'exons.bed.gz' '63f807c0cba04db8e5ab0a0c761f8f58a0e6933432e43e5b3b26558217f01724' 'bgzip -c "$IN" > "$OUT" && tabix -p bed "$OUT"' ''
export IN="$CACHE/ENCFF979PWH.bigWig" IN2="$ROOT/target/release/gloci"
derive 'ctcf-fc.bedgraph' '11bf90211107bda84eed99f30ef29177f792830e7877909bf2420cb4e9abcdaf' '"$IN2" convert "$IN" | sort -k1,1 -k2,2n -s > "$OUT"' 'ctcf-fc.bed5'
export IN="$CACHE/ctcf-fc.bedgraph"
derive 'ctcf-fc.bed5' '9fb50cd5cd59aa5d69599c7dd6dd0522eb734046855c28601ee5678b11896657' 'gawk -v OFS='\''\t'\'' '\''{print $1,$2,$3,".",$4}'\'' "$IN" > "$OUT"' ''
export IN="$CACHE/1kGP_high_coverage_Illumina.chr20.filtered.SNV_INDEL_SV_phased_panel.vcf.gz"
derive '1kg-chr20.bcf' '5041e7f9cd6cc55025ce0fd1b9d174c12851e503717df869c5a43e04771c9835' 'bcftools view --no-version -Ob -o "$OUT" "$IN" && bcftools index "$OUT"' ''
export IN="$CACHE/1kGP_high_coverage_Illumina.chr20.filtered.SNV_INDEL_SV_phased_panel.vcf.gz"
derive '1kg-chr20.p1.vcf.gz' '93be1bd3a387592d483471a626bcded73bad1769093c362e24040cd674097b27' 'bcftools index -f -t "$IN" && bcftools view --no-version -Oz -r chr20:1-30000000 -o "$OUT" "$IN" && bcftools index -t "$OUT"' ''
export IN="$CACHE/1kGP_high_coverage_Illumina.chr20.filtered.SNV_INDEL_SV_phased_panel.vcf.gz"
derive '1kg-chr20.p2.vcf.gz' 'f6f86390be54872fbe6f10b72a74ad181d19d88dd44e88f0a4c7ec4c34be6e22' 'bcftools index -f -t "$IN" && bcftools view --no-version -Oz -r chr20:30000001- -o "$OUT" "$IN" && bcftools index -t "$OUT"' ''
export IN="$CACHE/ENCFF834MPG.bam"
derive 'ctcf-k562.bam' '7e86b221c30456d5a10f988d272a5f5af978ab55336ab28f7301efeb81d3fdb3' 'cp "$IN" "$OUT" && samtools index -@ 4 "$OUT"' 'ctcf-k562.cram ctcf-peaks.bed'
export IN="$CACHE/ctcf-k562.bam"
derive 'ctcf-k562.cram' 'd65a67fb0f98abc76b3c7de888056c28cda4f4cde717f9c4d3e89303213111b1' 't=$(mktemp -d) && (cd "$t" && samtools view -C --output-fmt-option no_ref --no-PG -@ 0 -o c.cram "$IN" && samtools index c.cram) && mv "$t/c.cram.crai" "$OUT".crai && mv "$t/c.cram" "$OUT" && rmdir "$t"' ''
export IN="$CACHE/ENCFF769AUF.bed.gz" IN2="$CACHE/ctcf-k562.bam"
derive 'ctcf-peaks.bed' '2f669c78b6b56ee317fc9142a8a7a4be45f263f861828b01c715bffe6d300f9d' 'zcat "$IN" | cut -f1-6 | sort -k1,1 -k2,2n -s > "$OUT" && missing=$(comm -23 <(cut -f1 "$OUT" | sort -u) <(samtools view -H "$IN2" | gawk -F'\''\t'\'' '\''$1=="@SQ"{sub("SN:","",$2);print $2}'\'' | sort)) && [ -z "$missing" ] || { echo "contigs of the CTCF peaks that are not @SQ of the BAM: $missing" >&2; false; }' ''
export IN="$ROOT/crates/gloci-io/data/genomes/hg38.genome"
derive 'hg38.lex.genome' 'f0114a219fb57b6c3948c075a8ff9d0b87aa461b5a753f4e9aa749e7ad7a994d' 'sort -k1,1 "$IN" > "$OUT"' ''

if [ "$NUNPINNED" -gt 0 ]; then
  echo "$NUNPINNED derived inputs UNVERIFIED (no sha256 in datasets.toml):$UNPINNED" >&2
  if [ "${GLOCI_ALLOW_UNPINNED:-}" != 1 ]; then
    echo "set GLOCI_ALLOW_UNPINNED=1 to accept them while recording the digests" >&2
    exit 1
  fi
fi
